		ConfigDir:   filepath.Join(configHome, "direnv"),
		DataDir:     filepath.Join(dataHome, "direnv"),
		CacheDir:    filepath.Join(cacheHome, "direnv"),
		BashPath:    "/usr/bin/bash",
		WarnTimeout: 5 * time.Second,
	}

	if err := loadTomlConfig(&cfg); err != nil {
		return Config{}, err
	}
	if env := os.Getenv("DIRENV_WARN_TIMEOUT"); env != "" {
		if d, err := time.ParseDuration(env); err == nil {
			cfg.WarnTimeout = d
		}
	}
	return cfg, nil
}

func loadTomlConfig(cfg *Config) error {
	path := filepath.Join(cfg.ConfigDir, "direnv.toml")
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	defer file.Close()

	section := ""
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.TrimSpace(line[1 : len(line)-1])
			continue
		}
		key, val, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		key = strings.TrimSpace(key)
		val = strings.TrimSpace(val)
		switch section {
		case "global":
			switch key {
			case "bash_path":
				if s, err := parseTomlString(val); err == nil && s != "" {
					cfg.BashPath = s
				}
			case "disable_stdin":
				cfg.DisableStdin = parseTomlBool(val)
			case "load_dotenv":
				cfg.LoadDotenv = parseTomlBool(val)
			case "strict_env":
				cfg.StrictEnv = parseTomlBool(val)
			case "hide_env_diff":
				cfg.HideEnvDiff = parseTomlBool(val)
			case "warn_timeout":
				if s, err := parseTomlString(val); err == nil {
					if d, err := time.ParseDuration(s); err == nil {
						cfg.WarnTimeout = d
					}
				}
			case "log_format":
				if s, err := parseTomlString(val); err == nil {
					cfg.LogFormat = s
				}
			case "log_filter":
				if s, err := parseTomlString(val); err == nil && s != "" {
					if re, err := regexp.Compile(s); err == nil {
						cfg.LogFilter = re
					}
				}
			}
		case "whitelist":
			switch key {
			case "prefix":
				if list, err := parseTomlStringArray(val); err == nil {
					cfg.WhitelistPrefix = list
				}
			case "exact":
				if list, err := parseTomlStringArray(val); err == nil {
					cfg.WhitelistExact = list
				}
			}
		}
	}
	return scanner.Err()
}

func parseTomlString(raw string) (string, error) {
	raw = strings.TrimSpace(raw)
