	}

	for {
		envrc := filepath.Join(dir, ".envrc")
		if info, err := os.Stat(envrc); err == nil && !info.IsDir() {
			return &RC{Path: envrc, Dir: dir, Base: ".envrc"}, nil
		}
		if cfg.LoadDotenv {
			dotenv := filepath.Join(dir, ".env")
			if info, err := os.Stat(dotenv); err == nil && !info.IsDir() {
				return &RC{Path: dotenv, Dir: dir, Base: ".env", IsDotenv: true}, nil
			}
