func evaluateRC(cfg Config, rc *RC, baseEnv map[string]string) (evalResult, error) {
	return runEvalScript(cfg, rc, baseEnv, rc.IsDotenv)
}

func evaluateDotenv(cfg Config, path string, baseEnv map[string]string) (evalResult, error) {
	rc := &RC{
		Path:     path,
		Dir:      filepath.Dir(path),
		Base:     filepath.Base(path),
		IsDotenv: true,
	}
	return runEvalScript(cfg, rc, baseEnv, true)
}

func runEvalScript(cfg Config, rc *RC, baseEnv map[string]string, dotenv bool) (evalResult, error) {
	script := buildEvalScript(cfg, rc.Base, dotenv)
	cmd := exec.Command(cfg.BashPath, "-c", script)
	cmd.Dir = rc.Dir
	cmd.Env = envListFromMap(baseEnv)
	if cfg.DisableStdin {
		cmd.Stdin = strings.NewReader("")
	} else {
		cmd.Stdin = os.Stdin
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()

	var raw map[string]string
	if data := strings.TrimSpace(stdout.String()); data != "" {
		if jsonErr := json.Unmarshal(stdout.Bytes(), &raw); jsonErr != nil {
			return evalResult{}, jsonErr
		}
	} else {
		raw = map[string]string{}
	}
	if err != nil {
		return evalResult{Env: raw, Stderr: stderr.Bytes()}, err
	}
	return evalResult{Env: raw, Stderr: stderr.Bytes()}, nil
}

func buildEvalScript(cfg Config, base string, dotenv bool) string {
	var b strings.Builder
	b.WriteString(stdlibScript(cfg.SelfPath))
	b.WriteString("\n")
	b.WriteString(`exec 3>&1
exec 1>&2
__dump_at_exit() {
  local ret=$?
  "$direnv" dump json "" >&3
  trap - EXIT
  exit "$ret"
}
trap __dump_at_exit EXIT

for lib in "$direnv_config_dir/lib/"*.sh; do
  source "$lib"
done
if [[ -f $direnv_config_dir/direnvrc ]]; then
  source "$direnv_config_dir/direnvrc" >&2
elif [[ -f $HOME/.direnvrc ]]; then
  source "$HOME/.direnvrc" >&2
fi
`)
	if cfg.StrictEnv {
		b.WriteString("\nset -o errexit -o nounset -o pipefail\n")
	}
	if dotenv {
		b.WriteString("\nset -a\n")
	}
	fmt.Fprintf(&b, "source ./%s\n", shellEscapeWord(base))
	return b.String()
