		return nil, fmt.Errorf("sri: not a hash %s", integrity)
	}
	raw, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(integrity, "sha256-"))
	if err != nil {
		return nil, fmt.Errorf("sri: not a hash %s", integrity)
	}
	return raw, nil
}

func fetchURL(cfg Config, url, integrity string) error {
	body, err := httpGetBytes(url)
	if err != nil {
		return err
	}
	actual := sriSHA256(body)
	sum := sha256.Sum256(body)
	cachePath := filepath.Join(cfg.CacheDir, "cas", hex.EncodeToString(sum[:]))

	if integrity == "" {
		if err := os.MkdirAll(filepath.Dir(cachePath), 0o755); err != nil {
			return err
		}
		if _, err := os.Stat(cachePath); err != nil {
			if err := os.WriteFile(cachePath, body, 0o500); err != nil {
				return err
			}
			if err := os.Chmod(cachePath, 0o500); err != nil {
				return err
			}
		}
		if isTTY(os.Stdout) {
			fmt.Fprintf(os.Stdout, "Found hash: %s\n\n", actual)
			fmt.Fprintln(os.Stdout, "Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Fprintln(os.Stdout)
