		}
		return nil
	}

	expected, err := sriToHex(integrity)
	if err != nil {
		return err
	}
	if !strings.EqualFold(hex.EncodeToString(expected), hex.EncodeToString(sum[:])) {
		return fmt.Errorf("hash mismatch. Expected %q but got %q", integrity, actual)
	}
	if err := os.MkdirAll(filepath.Dir(cachePath), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(cachePath, body, 0o500); err != nil {
