+func stdlibScript(selfPath string) string {
+	return strings.ReplaceAll(stdlibTemplate, "__DIRENV_SELF__", selfPath)
+}
+
+func evaluateRC(cfg Config, rc *RC, baseEnv map[string]string, label string) (evalResult, error) {
+	return runEvalScript(cfg, rc, baseEnv, rc.IsDotenv, label)
+}
+
+func runEvalScript(cfg Config, rc *RC, baseEnv map[string]string, dotenv bool, label string) (evalResult, error) {
+	dumpFile, err := os.CreateTemp("", "direnv-dump-")
+	if err != nil {
+		return evalResult{}, err
+	}
+	dumpPath := dumpFile.Name()
+	if err := dumpFile.Close(); err != nil {
+		return evalResult{}, err
+	}
+	defer os.Remove(dumpPath)
+
+	script := buildEvalScript(cfg, rc.Base, dotenv)
+	cmd := exec.Command(cfg.BashPath, "-c", script)
+	cmd.Dir = rc.Dir
+	env := cloneEnv(baseEnv)
+	env["DIRENV_DUMP_FILE_PATH"] = dumpPath
+	cmd.Env = envListFromMap(env)
+	if cfg.DisableStdin {
+		cmd.Stdin = strings.NewReader("")
+	} else {
+		cmd.Stdin = os.Stdin
+	}
+
+	var stdout, stderr bytes.Buffer
+	cmd.Stdout = io.MultiWriter(os.Stdout, &stdout)
+	cmd.Stderr = io.MultiWriter(os.Stderr, &stderr)
+
+	done := make(chan struct{})
+	if cfg.WarnTimeout > 0 {
+		go func() {
+			select {
+			case <-time.After(cfg.WarnTimeout):
+				writeError(cfg, fmt.Sprintf("([%s]) is taking a while to execute. Use CTRL-C to give up.", label))
+			case <-done:
+			}
+		}()
+	}
+
+	err = cmd.Run()
+	close(done)
+
+	dumpData, readErr := os.ReadFile(dumpPath)
+	if readErr != nil && !os.IsNotExist(readErr) {
+		return evalResult{}, readErr
+	}
+	result := evalResult{Env: map[string]string{}}
+	if len(bytes.TrimSpace(dumpData)) > 0 {
+		if decodeErr := decodeObject(string(bytes.TrimSpace(dumpData)), &result.Env); decodeErr != nil {
+			return evalResult{}, decodeErr
+		}
+	}
+	return result, err
+}
+
+func buildEvalScript(cfg Config, base string, dotenv bool) string {
+	var b strings.Builder
+	b.WriteString(stdlibScript(cfg.SelfPath))
+	b.WriteString("\n")
+	b.WriteString(`for lib in "$direnv_config_dir/lib/"*.sh; do
+  # shellcheck disable=SC1090
+  source "$lib"
+done
+if [[ -f $direnv_config_dir/direnvrc ]]; then
+  # shellcheck disable=SC1090
+  source "$direnv_config_dir/direnvrc"
+elif [[ -f $HOME/.direnvrc ]]; then
+  # shellcheck disable=SC1090
+  source "$HOME/.direnvrc"
+fi
+`)
+	if cfg.StrictEnv {
+		b.WriteString("\nset -o errexit -o nounset -o pipefail\n")
+	}
+	if dotenv {
+		b.WriteString("\nset -a\n")
+	}
+	fmt.Fprintf(&b, "source ./%s\n", shellEscapeWord(base))
+	b.WriteString(`if [[ -n ${DIRENV_DUMP_FILE_PATH:-} ]]; then
+  "$direnv" dump >"$DIRENV_DUMP_FILE_PATH"
+fi
+`)
+	return b.String()
+}
+
+func sanitizeEvaluatedEnv(base, evaluated map[string]string, keepEnvrcMarker bool) map[string]string {
+	target := cloneEnv(base)
+	for key := range target {
+		if shouldIgnoreEvalKey(key) {
+			delete(target, key)
+		}
+	}
+	for key, val := range evaluated {
+		if key == "DIRENV_IN_ENVRC" {
+			if keepEnvrcMarker {
+				target[key] = val
+			}
+			continue
+		}
+		if shouldIgnoreEvalKey(key) {
+			continue
+		}
+		target[key] = val
+	}
+	for key := range target {
+		if key == "DIRENV_IN_ENVRC" {
+			if !keepEnvrcMarker {
+				delete(target, key)
+			}
+			continue
+		}
+		if shouldIgnoreEvalKey(key) {
+			delete(target, key)
+			continue
+		}
+		if _, ok := evaluated[key]; !ok {
+			delete(target, key)
+		}
+	}
+	for key, val := range base {
+		if shouldIgnoreEvalKey(key) {
+			target[key] = val
+		}
+	}
+	return target
+}
+
+func shouldIgnoreEvalKey(key string) bool {
+	if key == "PWD" || key == "OLDPWD" || key == "SHLVL" || key == "_" {
+		return true
+	}
+	if key != "DIRENV_IN_ENVRC" && strings.HasPrefix(key, "DIRENV_") {
+		return true
+	}
+	if strings.HasPrefix(key, "BASH_") {
+		return true
+	}
+	switch key {
+	case "EPOCHREALTIME", "EPOCHSECONDS", "FUNCNAME", "GROUPS", "DIRSTACK", "HOSTTYPE", "MACHTYPE", "OSTYPE", "OPTERR", "OPTIND", "PIPESTATUS", "PPID", "PS4", "SHELLOPTS", "UID", "EUID":
+		return true
+	default:
+		return false
+	}
+}
+
+func shellEscapeWord(word string) string {
+	var b strings.Builder
+	for _, r := range word {
+		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || strings.ContainsRune("._/-", r) {
+			b.WriteRune(r)
+		} else {
+			b.WriteString("\\" + string(r))
+		}
+	}
+	return b.String()
+}
